<?php /** The credential form (screen source-credential; ids source-credential-form-field-{name}): the current one's label and last four; kind, label, the username (SFTP), the secret — a password field, never pre-filled, never shown again. Data: s, kinds, back */ $id = (int) $s['source_id']; ?>
<?= view('shared/header.php', ['id' => 'source-credential', 'title' => 'Credential · ' . $s['name'], 'crumbs' => [['Home', '/'], ['POS sources', '/sales/sources/'], [$s['name'], '/sales/sources/' . $id], ['Credential', null]], 'back' => $back]) ?>
<div class="main-content" id="source-credential-content">
    <div class="card mb-3" id="source-credential-current"><div class="card-body fs-12"><?php if ($s['credentials'] === []): ?>No credential yet.<?php else: $c = $s['credentials'][0]; ?>Current: <strong><?= e($c['kind']) ?></strong> · <?= e($c['label']) ?> · …<span id="source-credential-last4"><?= e($c['last4']) ?></span> (set <?= e(format_date(substr((string) $c['created_at'], 0, 10))) ?>)<?php endif; ?></div></div>
    <?php if ($kinds === []): ?><div class="alert alert-info" id="source-credential-none">This source takes no credential — it is fed by upload or email.</div><?php else: ?>
    <form method="post" action="/sales/sources/<?= $id ?>/credential" hx-post="/sales/sources/credential.php" hx-target="#flash" id="source-credential-form" class="card" autocomplete="off">
        <?= csrf_field() ?><input type="hidden" name="source" value="<?= $id ?>">
        <div class="card-body">
            <div class="row mb-3 align-items-center"><div class="col-lg-4"><label class="fw-semibold" for="source-credential-form-field-kind">Kind</label></div><div class="col-lg-8"><select name="kind" id="source-credential-form-field-kind" class="form-select btn-touch"><?php foreach ($kinds as $k): ?><option value="<?= e($k) ?>"><?= e(str_replace('_', ' ', $k)) ?></option><?php endforeach; ?></select></div></div>
            <div class="row mb-3 align-items-center"><div class="col-lg-4"><label class="fw-semibold" for="source-credential-form-field-label">Label</label></div><div class="col-lg-8"><input type="text" name="label" id="source-credential-form-field-label" class="form-control btn-touch" maxlength="80" required placeholder="Square production token"></div></div>
            <?php if ($s['connector'] === 'file'): ?><div class="row mb-3 align-items-center"><div class="col-lg-4"><label class="fw-semibold" for="source-credential-form-field-username">SFTP user</label></div><div class="col-lg-8"><input type="text" name="username" id="source-credential-form-field-username" class="form-control btn-touch" autocomplete="off"></div></div><?php endif; ?>
            <div class="row mb-3 align-items-center"><div class="col-lg-4"><label class="fw-semibold" for="source-credential-form-field-secret">Secret</label></div><div class="col-lg-8"><input type="password" name="secret" id="source-credential-form-field-secret" class="form-control btn-touch" autocomplete="new-password" required><div class="form-text">Sealed under the server's key; shown again only as its last four.</div></div></div>
        </div>
        <div class="card-footer d-flex gap-2"><button type="submit" class="btn btn-primary btn-touch" id="source-credential-save"><?= $s['credentials'] === [] ? 'Set' : 'Rotate' ?></button><?= hx_link('/sales/sources/' . $id, 'Cancel', 'btn btn-light btn-touch') ?></div>
    </form><?php endif; ?>
</div>
